package org.brightstats.desktop;
import java.util.*;import com.google.gson.*;import org.brightstats.data.*;import org.brightstats.stats.*;
/** Authored, seeded synthetic teaching data. No vendor datasets or internet resources. */
final class StudioExamples {
 record Example(String name,String description,JsonObject project){Example{project=project.deepCopy();}@Override public JsonObject project(){return project.deepCopy();}}
 static List<Example> all(){return List.of(missing(),ordinal(),clustered());}
 static JsonObject project(List<String> names,List<List<String>> rows,List<DataPreparation.Column> columns,DataPreparation.Missing missing,long seed){var raw=new DataPreparation.Raw(names,rows);var settings=new DataPreparation.Settings(',',DataPreparation.Decimal.DOT,"",missing);var prepared=DataPreparation.prepare(raw,settings,columns);Gson gson=new Gson();JsonObject project=new JsonObject();project.addProperty("format","bright-stats-project");project.addProperty("formatVersion",1);project.add("columnNames",gson.toJsonTree(prepared.columns()));project.add("observations",gson.toJsonTree(prepared.values()));project.add("blocks",new JsonArray());project.add("edges",new JsonArray());project.add("dataPreparation",ImportHistory.capture("Authored synthetic example; seed "+seed,raw,settings,columns));return project;}
 static SemModel.Model marginal(List<String> names){int p=names.size();List<SemModel.Parameter> parameters=new ArrayList<>();for(int i=0;i<p;i++){parameters.add(new SemModel.Parameter("Mean "+names.get(i),List.of(new SemModel.Location(SemModel.Kind.INTERCEPT,i,0)),0,1));for(int j=0;j<=i;j++)parameters.add(new SemModel.Parameter(i==j?"Variance "+names.get(i):"Covariance "+names.get(i)+" / "+names.get(j),List.of(new SemModel.Location(SemModel.Kind.COVARIANCE,i,j)),i==j?1:.2,1,i==j?1e-6:null,null));}return new SemModel.Model(names,java.util.stream.IntStream.range(0,p).toArray(),new double[p][p],new double[p][p],new double[p],parameters);}
 static Example missing(){Random rng=new Random(20261105);List<List<String>> rows=new ArrayList<>();for(int i=0;i<180;i++){double x=rng.nextGaussian(),y=.6*x+rng.nextGaussian();rows.add(List.of(Double.toString(x),x>0&&rng.nextDouble()<.35?"":Double.toString(y)));}var columns=List.of(new DataPreparation.Column("X",DataPreparation.Kind.NUMERIC),new DataPreparation.Column("Y",DataPreparation.Kind.NUMERIC));JsonObject project=project(List.of("X","Y"),rows,columns,DataPreparation.Missing.MEAN_REPLACEMENT,20261105);var options=new CovarianceSem.Options(1000,1e-8,1e-12,CovarianceSem.Likelihood.NORMAL,true,.95,CovarianceSem.Information.OBSERVED);project.add("semOptions",new Gson().toJsonTree(new SemDialog.Settings(options,true,marginal(List.of("X","Y")))));return new Example("Missingness laboratory","180 synthetic rows. Compare FIML and continuous multiple imputation using original missing cells; the visible prepared grid is mean-replaced. Assumed MAR generation is illustrative, not evidence about your data.",project);}
 static Example ordinal(){Random rng=new Random(20261106);List<String> names=List.of("X1","X2","X3","Y1","Y2","Y3");List<List<String>> rows=new ArrayList<>();for(int i=0;i<300;i++){double x=rng.nextGaussian(),y=.55*x+Math.sqrt(1-.55*.55)*rng.nextGaussian();List<String> row=new ArrayList<>();for(int j=0;j<6;j++){double z=.8*(j<3?x:y)+.6*rng.nextGaussian();int level=z<-.9?1:z<-.3?2:z<.3?3:z<.9?4:5;row.add(Integer.toString(level));}rows.add(row);}var definitions=names.stream().map(n->new DataPreparation.Column(n,DataPreparation.Kind.NUMERIC)).toList();JsonObject project=project(names,rows,definitions,DataPreparation.Missing.REMOVE_ROWS,20261106);var blocks=List.of(new PlsSem.Block("Experience",new int[]{0,1,2},PlsSem.Mode.A),new PlsSem.Block("Outcome",new int[]{3,4,5},PlsSem.Mode.A));var edges=List.of(new PlsSem.Edge(0,1));var levels=names.stream().map(n->List.of("1","2","3","4","5")).toList();project.add("ordinalSettings",new Gson().toJsonTree(new OrdinalDialog.Settings(names,blocks,edges,new OrdinalData.Specification(names,levels,false),OrdinalSem.Options.defaults())));JsonArray diagram=new JsonArray();for(int j=0;j<2;j++){JsonObject node=new Gson().toJsonTree(blocks.get(j)).getAsJsonObject();node.addProperty("x",230+j*400);node.addProperty("y",270);diagram.add(node);}project.add("blocks",diagram);project.add("edges",new Gson().toJsonTree(edges));return new Example("Ordered-response studio","Two reflective factors, six declared five-level indicators, 300 synthetic cases. Explore polychoric moments, robust ordinal intervals and residual heatmaps.",project);}
 static Example clustered(){Random rng=new Random(20261107);List<List<String>> rows=new ArrayList<>();for(int g=0;g<24;g++){double shared=.65*rng.nextGaussian();for(int i=0;i<6;i++)rows.add(List.of("Group "+(g+1),Double.toString(.3+shared+rng.nextGaussian())));}JsonObject project=project(List.of("Cluster","Y"),rows,List.of(new DataPreparation.Column("Cluster",DataPreparation.Kind.TEXT),new DataPreparation.Column("Y",DataPreparation.Kind.NUMERIC)),DataPreparation.Missing.REMOVE_ROWS,20261107);var model=marginal(List.of("Y"));project.add("clusterSettings",new Gson().toJsonTree(new ClusterDialog.Settings(0,"Cluster",false,false,model,null,ClusterSem.Options.defaults())));return new Example("Cluster-aware research","24 synthetic groups, six cases each. Fit cluster-sandwich inference or explicitly configure a within/between model; cases share a simulated group effect.",project);}
}
